<?php
if(!defined('ABSPATH'))exit;
function dgs_gallery_elementor_section($title='گالری تصاویر مدرسه'){return dgs_es_section(array(dgs_es_column(array(dgs_es_live('gallery',array('count'=>8,'gallery_title'=>$title))),100)),false,array('css_classes'=>'dse-section dgg-gallery-section'));}
function dgs_gallery_portal_intro(){return dgs_es_column(array(dgs_es_widget('dgs_icon',array('icon_name'=>'login','align'=>'right','size'=>array('size'=>25,'unit'=>'px'))),dgs_es_heading('ورود به سامانه مدرسه','h2',17),dgs_es_text('دسترسی به پنل اختصاصی بر اساس نقش شما در مدرسه دانشگران')),20);}
function dgs_gallery_compact_portal($section){
 $columns=$section['elements']??array();if(count($columns)!==3)return null;$roles=array();foreach($columns as $column){$role='';foreach($column['elements']??array() as $w)if(($w['widgetType']??'')==='button'){$query=wp_parse_url($w['settings']['link']['url']??'',PHP_URL_QUERY);parse_str((string)$query,$params);if(in_array($params['login_role']??'',array('student','teacher','manager'),true))$role=$params['login_role'];}if(!$role)return null;$roles[]=$role;}if(count(array_unique($roles))!==3)return null;
 foreach($columns as &$column){$column['settings']['_column_size']=80/3;$column['settings']['css_classes']=trim(($column['settings']['css_classes']??'').' dgg-portal-card');$column['settings']['padding']=array('unit'=>'px','top'=>'10','right'=>'8','bottom'=>'10','left'=>'8','isLinked'=>false);foreach($column['elements'] as &$w){$type=$w['widgetType']??'';if($type==='heading'){$w['settings']['typography_font_size']=array('size'=>15,'unit'=>'px');$w['settings']['typography_font_size_mobile']=array('size'=>16,'unit'=>'px');}elseif($type==='text-editor')$w['settings']['typography_font_size']=array('size'=>11,'unit'=>'px');elseif($type==='button'){$w['settings']['typography_font_size']=array('size'=>11,'unit'=>'px');$w['settings']['button_padding']=array('unit'=>'px','top'=>'4','right'=>'18','bottom'=>'4','left'=>'18','isLinked'=>false);$w['settings']['border_radius']=array('unit'=>'px','top'=>'22','right'=>'22','bottom'=>'22','left'=>'22','isLinked'=>true);}elseif($type==='dgs_icon')$w['settings']['size']=array('size'=>26,'unit'=>'px');}unset($w);}unset($column);
 $intro=dgs_gallery_portal_intro();$intro['settings']['css_classes']='dgg-portal-intro';$section['elements']=array_merge(array($intro),$columns);$section['settings']['css_classes']=trim(($section['settings']['css_classes']??'').' dgg-portal-panel');$section['settings']['background_background']='classic';$section['settings']['background_color']='#f9f5ff';$section['settings']['border_border']='solid';$section['settings']['border_color']='#dbc1ed';$section['settings']['border_width']=array('unit'=>'px','top'=>'1','right'=>'1','bottom'=>'1','left'=>'1','isLinked'=>true);$section['settings']['border_radius']=array('unit'=>'px','top'=>'15','right'=>'15','bottom'=>'15','left'=>'15','isLinked'=>true);return $section;
}
function dgs_gallery_section_widgets($node){$out=array();if(($node['elType']??'')==='widget')$out[]=$node;foreach($node['elements']??array() as $child)$out=array_merge($out,dgs_gallery_section_widgets($child));return $out;}
function dgs_gallery_transform_data($data){
 $out=array();$changed=false;$gallery_done=false;foreach($data as $section){$widgets=dgs_gallery_section_widgets($section);$old_gallery=count($widgets)===4;foreach($widgets as $w){if(($w['widgetType']??'')==='dgs_live'&&($w['settings']['kind']??'')==='gallery')$gallery_done=true;if(($w['widgetType']??'')!=='dgs_picture'||!preg_match('/^gallery[0-3]$/D',$w['settings']['reference']??''))$old_gallery=false;}
 if($old_gallery&&!$gallery_done){$title='گالری تصاویر مدرسه';if($out){$previous=dgs_gallery_section_widgets(end($out));if(count($previous)===1&&($previous[0]['widgetType']??'')==='heading'){$title=wp_strip_all_tags($previous[0]['settings']['title']??$title);array_pop($out);}}$out[]=dgs_gallery_elementor_section($title);$gallery_done=true;$changed=true;continue;}
 if(strpos($section['settings']['css_classes']??'','dgg-portal-panel')===false){$portal=dgs_gallery_compact_portal($section);if($portal){$section=$portal;$changed=true;}}$out[]=$section;}
 return array('data'=>$out,'changed'=>$changed);
}
function dgs_gallery_upgrade_elementor(){
 if(!current_user_can('manage_options'))return;foreach(dgs_elementor_targets() as $id){if(!dgs_elementor_converted($id)||get_post_meta($id,'_dgs_gallery_layout_019',true)==='1')continue;$lock='dgs_gallery_layout_lock_'.$id;if(!add_option($lock,time(),'','no')){if((int)get_option($lock)<time()-180)delete_option($lock);continue;}
 $write_attempted=false;$backup=null;try{$raw=get_post_meta($id,'_elementor_data',true);$data=json_decode($raw,true);if(!is_array($data))continue;$result=dgs_gallery_transform_data($data);if($result['changed']){$backup=dgs_elementor_snapshot($id);if(!metadata_exists('post',$id,'_dgs_gallery_roles_backup_019'))update_post_meta($id,'_dgs_gallery_roles_backup_019',wp_slash($backup));$stored=get_post_meta($id,'_dgs_gallery_roles_backup_019',true);if(!is_array($stored)||!isset($stored['content'],$stored['meta']))continue;\Elementor\Plugin::$instance->widgets_manager->get_widget_types();$doc=\Elementor\Plugin::$instance->documents->get($id);if(!$doc||get_post_meta($id,'_elementor_data',true)!==$raw)continue;$write_attempted=true;if(!$doc->save(array('elements'=>$result['data']))){dgs_elementor_restore_snapshot($id,$backup);continue;}delete_post_meta($id,'_elementor_css');dgs_gallery_invalidate($id);}update_post_meta($id,'_dgs_gallery_layout_019','1');}
 catch(Throwable $error){if($write_attempted&&is_array($backup))dgs_elementor_restore_snapshot($id,$backup);set_transient('dgs_gallery_layout_notice_'.get_current_user_id(),'اصلاح خودکار بخش گالری کامل نشد؛ می‌توانید ویجت اطلاعات زنده دانشگران با نوع گالری را از المنتور اضافه کنید.',120);}
 finally{delete_option($lock);}}
}
add_action('admin_notices',function(){if(!current_user_can('manage_options'))return;$screen=get_current_screen();if($screen&&$screen->post_type==='dgs_gallery')echo '<div class="notice notice-info"><p>عنوان و توضیح را بنویسید، از کادر «تصویر گالری» عکس را انتخاب یا بارگذاری کنید و انتشار را بزنید. <a href="'.esc_url(dgs_gallery_url()).'">مشاهده گالری کامل سایت</a></p></div>';$text=get_transient('dgs_gallery_layout_notice_'.get_current_user_id());if($text){delete_transient('dgs_gallery_layout_notice_'.get_current_user_id());echo '<div class="notice notice-warning"><p>'.esc_html($text).'</p></div>';}});
